        SELECT 1 FROM pg_constraint c
        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
        WHERE c.conrelid = to_regclass('payment.aging_buckets') AND c.contype = 'f' AND a.attname = 'snapshot_id'
    ) THEN
        ALTER TABLE payment.aging_buckets ADD CONSTRAINT fk_aging_buckets_snapshot_id FOREIGN KEY (snapshot_id) REFERENCES payment.aging_snapshots (id) NOT VALID;
        BEGIN
            ALTER TABLE payment.aging_buckets VALIDATE CONSTRAINT fk_aging_buckets_snapshot_id;
        EXCEPTION WHEN foreign_key_violation THEN
            RAISE NOTICE 'fk_aging_buckets_snapshot_id left NOT VALID: stored rows of payment.aging_buckets reference missing rows';
        END;
    END IF;
END $$;

